String headerIgnoreCase(def headers, def names) {
  if (!(headers instanceof Map)) {
    return null;
  }
  for (name in names) {
    def v = headers.get(name);
    if (v != null) {
      String s = v.toString().trim();
      if (!s.isEmpty()) {
        return s;
      }
    }
  }
  for (entry in headers.entrySet()) {
    def k = entry.getKey();
    if (k == null) {
      continue;
    }
    String lk = k.toString().toLowerCase();
    for (name in names) {
      if (lk.equals(((String) name).toLowerCase())) {
        def v = entry.getValue();
        if (v != null) {
          String s = v.toString().trim();
          if (!s.isEmpty()) {
            return s;
          }
        }
      }
    }
  }
  return null;
}
def tid = ctx.trace != null ? ctx.trace.id : null;
def tnt = ctx.tnt;
if (tnt == null) {
  tnt = headerIgnoreCase(ctx.aws?.waf?.request?.headers, ['tnt', 'Tnt', 'TNT', 'tenant', 'Tenant', 'tenantid']);
}
def out = new HashMap();
out.put('@timestamp', ctx['@timestamp']);
if (tid != null) {
  def tr = new HashMap();
  tr.put('id', tid);
  out.put('trace', tr);
}
if (tnt != null) {
  out.put('tnt', tnt.toString().trim());
}
def action = ctx.event != null ? ctx.event.action : null;
if (action != null) {
  def ev = new HashMap();
  ev.put('action', action);
  out.put('event', ev);
}
def ruleId = ctx.rule != null ? ctx.rule.id : null;
if (ruleId != null) {
  def rule = new HashMap();
  rule.put('id', ruleId);
  out.put('rule', rule);
}
def arn = ctx.aws?.waf?.arn;
if (arn != null) {
  def waf = new HashMap();
  waf.put('arn', arn);
  def aws = new HashMap();
  aws.put('waf', waf);
  out.put('aws', aws);
}
def reqId = ctx.http?.request?.id;
if (reqId != null) {
  def req = new HashMap();
  req.put('id', reqId);
  def http = new HashMap();
  http.put('request', req);
  out.put('http', http);
}
def keys = new ArrayList(ctx.keySet());
for (k in keys) {
  if (k.equals('_index') || k.equals('_id') || k.equals('_routing') || k.equals('_version')) {
    continue;
  }
  ctx.remove(k);
}
ctx.putAll(out);
if (tid != null) {
  ctx._id = tid;
}
